if(f.id==='automation-rule-form'){try{const d=new FormData(f),name=String(d.get('name')||'').trim(),trigger=String(d.get('trigger')||''),actionType=String(d.get('actionType')||''),conditionMode=String(d.get('conditionMode')||'all'),delayDays=Number(d.get('delayDays')),withinDays=Number(d.get('withinDays')),maxRunsPerDay=Number(d.get('maxRunsPerDay')),quietStart=String(d.get('quietStart')||''),quietEnd=String(d.get('quietEnd')||''),scheduleTime=String(d.get('scheduleTime')||''),conditions=parseAutomationConditions(d.get('conditions')||'');if(!name||!automationTriggers.some(x=>x.id===trigger)||!automationActions.some(x=>x.id===actionType))throw Error('Give your rule a name and choose a supported trigger and local action.');if(!['all','any'].includes(conditionMode)||conditions.length>10)throw Error('Choose AND/OR conditions, with no more than ten checks.');if(!Number.isInteger(delayDays)||delayDays<1||delayDays>90||!Number.isInteger(withinDays)||withinDays<1||withinDays>30||!Number.isInteger(maxRunsPerDay)||maxRunsPerDay<1||maxRunsPerDay>25)throw Error('Keep delay, due window and approval cap within the displayed limits.');if(Boolean(quietStart)!==Boolean(quietEnd)||quietStart&&quietEnd&&quietStart===quietEnd)throw Error('Choose two different quiet-hour times, or leave both blank.');if(trigger==='scheduled-review'&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(scheduleTime))throw Error('Choose the local time for your scheduled review.');await act(()=>store.update(s=>s.rules.push({id:uid(),automationVersion:1,name,trigger,actionType,conditionMode,conditions,delayDays,withinDays,maxRunsPerDay,quietStart,quietEnd,scheduleTime,enabled:d.has('enabled'),createdAt:now(),timezone:s.settings.timezone,requiresApproval:true,actions:[actionType]})),`Rule saved ${d.has('enabled')?'and enabled':'off'}. Preview before approving any suggestions. ♡`);}catch(err){error(err.message)}return;}
