function careerPrepPanel(){const applications=records('application'),entries=records('note').filter(x=>x.tags.includes('Interview preparation'));return `<section class="panel career-prep"><span class="tiny-label">PREPARE, REFLECT & FOLLOW THROUGH</span><h2>Interview studio</h2>${applications.length?`<form id="career-prep-form" class="formgrid"><label>Application<select name="application" required>${applications.map(x=>`<option value="${esc(x.id)}">${esc(x.data.company||x.title)} · ${esc(x.title)}</option>`).join('')}</select></label><label>Interview date (optional)<input name="date" type="date"></label><label>Current outcome<select name="outcome"><option>Preparing</option><option>Interviewed</option><option>Follow-up sent</option><option>Offer</option><option>No offer</option></select></label><label class="span2">Questions to prepare<textarea name="questions" maxlength="5000" placeholder="Role questions, likely prompts, or questions you want to rehearse"></textarea></label><label class="span2">Evidence and examples<textarea name="evidence" maxlength="5000" placeholder="Projects, outcomes, strengths, and examples from your actual experience"></textarea></label><label class="span2">Questions to ask them<textarea name="questionsToAsk" maxlength="5000" placeholder="Team, expectations, support, schedule, compensation"></textarea></label><label class="span2">Reflection or next steps<textarea name="reflection" maxlength="5000" placeholder="What felt clear? What do you want to learn or follow up on?"></textarea></label><label class="span2">Follow-up draft<textarea name="followupDraft" maxlength="5000" placeholder="A draft stays here for you to review and send yourself"></textarea></label><button class="heart-pill" type="submit">Save interview prep ♡</button></form>`:'<p class="calmempty">Add an application to prepare for an interview.</p>'}<h3>Preparation notes</h3>${entries.length?entries.slice().reverse().map(x=>`<article class="category-row"><div><strong>${esc(x.title)}</strong><small>${esc(x.data.interviewDate||'Date not set')} · ${esc(x.data.outcome||'Preparing')}</small><p>${esc(x.body)}</p><small>Linked application: ${esc(applications.find(a=>a.id===x.data.careerApplicationId)?.title||'Application no longer active')}</small></div></article>`).join(''):'<p class="caption">Your prep notes, examples, reflections, and follow-up drafts will appear here.</p>'}<p class="caption">Marked sensitive and excluded from global search previews by default. Draft follow-ups stay local and are not sent automatically.</p></section>`;}
function studioWorkspacePanel(){const ledger=studioLedger(active(store.state)),clients=records('client'),projects=records('project').filter(x=>x.tags.includes('Studio')||x.data.studioClientId||x.data.proposalId),quotes=records('proposal').filter(x=>x.tags.includes('Studio Estimate')),milestones=records('studioMilestone'),payments=records('studioPayment'),changes=records('studioChange'),deliverables=records('deliverable'),outreach=records('studioOutreach'),qas=records('launchQA');const projectOptions=projects.map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('');return `<section class="panel studio-operations"><div class="panelhead"><div><span class="tiny-label">A. HALLIWELL STUDIO · DELIVERY DESK</span><h2>Scope it, approve it, deliver it</h2></div><span class="tag">${projects.length} active projects</span></div><p>Draft estimates stay estimates. Invoices stay separate. Only a payment you explicitly mark received creates a received-cash transaction.</p><div class="money-stats"><div><span>ESTIMATES</span><strong>${dollars(ledger.estimateCents)}</strong><small>Draft or sent quotes</small></div><div><span>INVOICED</span><strong>${dollars(ledger.invoiceCents)}</strong><small>Invoices on file</small></div><div><span>RECEIVED STUDIO CASH</span><strong>${dollars(ledger.receivedCents)}</strong><small>Income transactions recorded</small></div></div><div class="lowergrid twocol"><section><h3>Scope & quote builder</h3><form id="studio-quote-form" class="formgrid"><label>Quote / project name<input name="title" required maxlength="160"></label><label>Client<select name="clientId"><option value="">No client linked yet</option>${clients.map(c=>`<option value="${esc(c.id)}">${esc(c.data.company||c.title)}</option>`).join('')}</select></label><label>Prospect<select name="leadId"><option value="">No prospect linked yet</option>${records('lead').filter(x=>!x.data.suppressContact).map(c=>`<option value="${esc(c.id)}">${esc(c.data.company||c.title)}</option>`).join('')}</select></label><label class="span2">Scope overview<textarea name="scope" required maxlength="3000"></textarea></label><label class="span2">Line items, one per line: deliverable | quantity | unit price<textarea name="lines" required placeholder="Homepage design | 1 | 1200.00&#10;Responsive build | 1 | 1800.00"></textarea></label><label class="span2">Assumptions, exclusions and payment terms<textarea name="assumptions" maxlength="3000" placeholder="What is included, what is outside scope, revision limits, payment milestones"></textarea></label><button class="heart-pill">Calculate estimate preview ♡</button></form>${studioQuoteDraft?`<div id="studio-quote-preview" role="status"><h4>${esc(studioQuoteDraft.title)}</h4>${studioQuoteDraft.quote.items.map(i=>`<div class="category-row"><span>${esc(i.label)} · ${i.quantity} × ${dollars(i.unitPriceCents)}</span><b>${dollars(i.lineTotalCents)}</b></div>`).join('')}<div class="category-row"><strong>Estimated total</strong><strong>${dollars(studioQuoteDraft.quote.totalCents)}</strong></div><p>${esc(studioQuoteDraft.scope)}</p><button class="softbutton" data-action="studio-quote-save">Save as draft estimate</button></div>`:'<p class="caption">Review the math and scope before saving a draft estimate.</p>'}</section><section><h3>Quote status & project start</h3>${quotes.map(q=>`<article class="category-row"><div><strong>${esc(q.title)}</strong><small>${dollars(q.data.amount||0)} · ${esc(q.data.status||'Draft')} · estimate only</small></div><div class="centeractions"><button class="textbutton" data-action="edit" data-id="${esc(q.id)}">Edit</button>${q.data.status==='Draft'?`<button class="softbutton" data-action="studio-quote-status" data-id="${esc(q.id)}" data-status="Sent">Mark as sent</button>`:''}${['Draft','Sent'].includes(q.data.status)?`<button class="softbutton" data-action="studio-quote-status" data-id="${esc(q.id)}" data-status="Accepted">Record client approval</button>`:''}${q.data.status==='Accepted'&&!projects.some(p=>p.data.proposalId===q.id)?`<button class="softbutton" data-action="studio-project-start" data-id="${esc(q.id)}">Start delivery project</button>`:''}<button class="iconbutton" data-action="trash" data-id="${esc(q.id)}" aria-label="Move ${esc(q.title)} to trash">${icon('trash')}</button></div></article>`).join('')||'<p>No Studio estimates yet.</p>'}<div class="centeractions"><button class="softbutton" data-action="new" data-type="invoice">Create invoice record</button><button class="softbutton" data-action="new" data-type="client">Add client</button></div><p class="caption">A quote is not an invoice. An invoice is not received cash. Record each milestone payment only after it arrives.</p></section></div><div class="lowergrid twocol"><section><h3>Project milestones</h3>${projects.length?`<form id="studio-milestones-form" class="formgrid"><label>Project<select name="projectId" required>${projectOptions}</select></label><label class="span2">Milestones: name | amount | due date<textarea name="items" required placeholder="Discovery | 1000.00 | 2026-11-05&#10;Launch | 1500.00 | 2026-11-20"></textarea></label><button class="softbutton">Save milestone plan ♡</button></form>`:'<p>Create a project from a client-approved estimate to plan delivery.</p>'}${milestones.map(m=>`<div class="category-row"><button class="textbutton" data-action="edit" data-id="${esc(m.id)}">${esc(m.title)}</button><small>${dollars(m.data.amount||0)} · ${esc(m.data.dueDate||'No date')} · ${esc(m.data.status||'Planned')}</small>${m.data.status!=='Done'?`<button class="softbutton" data-action="studio-milestone-done" data-id="${esc(m.id)}">Mark done</button>`:''}</div>`).join('')||'<p>No milestones saved.</p>'}</section><section><h3>Payment schedule</h3>${projects.length?`<form id="studio-payment-form" class="formgrid"><label>Project<select name="projectId" required>${projectOptions}</select></label><label>Payment milestone<input name="title" required></label><label>Expected amount ($)<input name="amount" inputmode="decimal" required></label><label>Expected date<input name="dueDate" type="date"></label><button class="softbutton">Save expected payment ♡</button></form>`:''}${payments.map(p=>`<div class="category-row"><span>${esc(p.title)} · ${dollars(p.data.amount||0)}</span><small>${esc(p.data.status||'Expected')} ${p.data.dueDate?'· '+esc(p.data.dueDate):''}</small>${p.data.status!=='Received'?`<button class="softbutton" data-action="studio-payment-received" data-id="${esc(p.id)}">Record received</button>`:''}</div>`).join('')||'<p>No payment milestones scheduled.</p>'}</section></div><div class="lowergrid twocol"><section><h3>Scope changes & revisions</h3>${projects.length?`<form id="studio-change-form" class="formgrid"><label>Project<select name="projectId" required>${projectOptions}</select></label><label>Change title<input name="title" required maxlength="160"></label><label class="span2">Requested change<textarea name="request" required maxlength="3000"></textarea></label><label>Estimate impact ($)<input name="amount" inputmode="decimal" value="0.00" required></label><label>Schedule impact (days)<input name="daysImpact" type="number" min="0" max="365" value="0"></label><button class="softbutton">Log change for approval ♡</button></form>`:''}${changes.map(c=>`<div class="category-row"><span>${esc(c.title)}</span><small>${esc(c.data.approval||'Awaiting approval')} · ${dollars(c.data.amount||0)} · ${Number(c.data.daysImpact)||0} days</small><button class="textbutton" data-action="edit" data-id="${esc(c.id)}">Review</button></div>`).join('')||'<p>No scope changes recorded.</p>'}</section><section><h3>Deliverables</h3>${projects.length?`<form id="studio-deliverable-form" class="formgrid"><label>Project<select name="projectId" required>${projectOptions}</select></label><label>Deliverable<input name="title" required maxlength="160"></label><label>Due date<input name="dueDate" type="date"></label><label>Link<input name="url" type="url"></label><label class="span2">Notes<textarea name="notes" maxlength="2000"></textarea></label><button class="softbutton">Add deliverable ♡</button></form>`:''}${deliverables.map(d=>`<div class="category-row"><button class="textbutton" data-action="edit" data-id="${esc(d.id)}">${esc(d.title)}</button><small>${esc(d.data.status||'Planned')} · ${esc(d.data.dueDate||'No date')}</small></div>`).join('')||'<p>No deliverables yet.</p>'}</section></div><div class="lowergrid twocol"><section><h3>Outreach log</h3><form id="studio-outreach-form" class="formgrid"><label>Business<input name="title" required maxlength="160"></label><label>Contact<input name="contact" maxlength="160"></label><label>Channel<select name="channel"><option>Email</option><option>Phone</option><option>Social</option><option>Referral</option><option>Meeting</option><option>Other</option></select></label><label>Next follow-up date<input name="followup" type="date"></label><label>Outcome<input name="outcome" maxlength="500"></label><label class="span2">Notes<textarea name="notes" maxlength="2000"></textarea></label><button class="softbutton">Log outreach ♡</button></form>${outreach.slice(-8).reverse().map(o=>`<div class="category-row"><span>${esc(o.title)} · ${esc(o.data.channel||'')}</span><small>${esc(o.data.outcome||'No outcome entered')} ${o.data.followup?'· follow up '+esc(o.data.followup):''}</small><button class="textbutton" data-action="edit" data-id="${esc(o.id)}">Edit</button></div>`).join('')||'<p>No outreach logged.</p>'}</section><section><h3>Launch QA</h3>${projects.length?`<form id="studio-qa-form" class="formgrid"><label>Project<select name="projectId" required>${projectOptions}</select></label><label>Checklist name<input name="title" required value="Launch review"></label><label class="span2">QA checks, one per line<textarea name="items" required placeholder="Mobile layout reviewed&#10;Contact form tested&#10;Client approval received"></textarea></label><button class="softbutton">Create QA checklist ♡</button></form>`:''}${qas.map(q=>{const p=homeChecklistProgress(q);return `<article class="recordcard"><h4>${esc(q.title)} · ${p.done}/${p.total}</h4>${p.items.map(i=>`<button class="checkrow ${i.done?'checked':''}" data-action="studio-qa-toggle" data-id="${esc(q.id)}" data-index="${i.index}" data-checked="${i.done?'true':'false'}" aria-pressed="${i.done}">${i.done?'✓':'○'} ${esc(i.title)}</button>`).join('')}<button class="textbutton" data-action="edit" data-id="${esc(q.id)}">Edit checklist</button></article>`;}).join('')||'<p>No launch checklists.</p>'}</section></div></section>`+studioLeadPanel();}
